import{_ as o,l as n,o as e,c as i,v as t,p as s,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"HNSW / IVF","description":"","frontmatter":{"title":"HNSW / IVF","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/hnsw-ivf.md","filePath":"llm/hnsw-ivf.md","lastUpdated":1789023840000}'),c={name:"llm/hnsw-ivf.md"};function m(_,a,f,N,S,u){const l=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="hnsw-ivf" tabindex="-1">HNSW / IVF <a class="header-anchor" href="#hnsw-ivf" aria-label="Permalink to &quot;HNSW / IVF&quot;">​</a></h1><div class="epigraph"><p>精确近邻随库规模线性扫。近似近邻用图或倒排粗量化换召回–延迟曲线。曲线是协议，不是「开了 HNSW 就无损」。</p><footer>—— Malkov &amp; Yashunin HNSW；Jégou 等 IVF 粗量化倒排</footer></div><p><a href="/llm/rag-context-compression">上一课</a>减少进入阅读器的 token。检索库本身仍可能是千万级向量。本课写 ANN 的两条默认结构：HNSW（图）与 IVF（倒排文件）。缺口是召回率对 \\(k\\)、efSearch、nprobe 的依赖。后课 PQ 在向量内部再压缩，常与 IVF 联用。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>精确 kNN 扫全库，延迟不可接受。HNSW 建多层可导航小世界图，搜索沿边贪心 + 候选集。IVF 先把空间分成粗心，查询只扫近的若干列表。二者都是近似：可能丢掉真正的邻居。RAG 里丢掉的若是唯一支撑块，忠实度直接掉。必须在<strong>自己的查询分布</strong>上画 Recall–延迟曲线，不能抄基准数字。</p><p>过滤（权限、租户）与图遍历交互：先过滤后搜或边搜边滤，实现错了会漏召回或漏出无权限文档。</p><p><span class="marginnote">建索引的超参（M、efConstruction、粗心个数）改的是图/列表质量，搜时的 efSearch / nprobe 改的是预算。两套都要进模型卡式的索引卡。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选结构：内存允许、要高召回 → HNSW；库极大、可接受较低召回或配合 PQ → IVF。调参：固定延迟预算扫 efSearch 或 nprobe，看 Recall@\\(k\\)。\\(k\\) 应大于最终送给阅读器的块数，给融合与压缩留候选。增量插入：HNSW 可动态加边，IVF 列表 unbalanced 时要重建。</p>',9)),(e(),s(p,null,{default:r(()=>[h(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20QV%5B%22%E6%9F%A5%E8%AF%A2%E5%90%91%E9%87%8F%22%5D%20--%3E%20HNSW%5B%22HNSW%20%E5%9B%BE%E9%81%8D%E5%8E%86%22%5D%0A%20%20QV%20--%3E%20IVF%5B%22IVF%20%E9%80%89%E5%88%97%E8%A1%A8%E5%86%8D%E6%89%AB%22%5D%0A%20%20HNSW%20--%3E%20CAND%5B%22%E8%BF%91%E4%BC%BC%20Top-n%22%5D%0A%20%20IVF%20--%3E%20CAND%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>HNSW 的高层边是长距离高速公路，底层是精细邻居。efSearch 增大等于允许更宽的候选，逼近精确。IVF 的误差来自查询落在错误粗心附近——边界点会被切错列表，nprobe 增大即多探几个心。两者都把「真实近邻被剪掉」的概率换成延迟。这个概率在难查询（近邻很近、易混）上更高，平均召回会掩盖切片。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>ANN 不修复坏嵌入。空间本身塌了，图再好也搜不到。下一课 PQ：把向量量化进码本，内存再降一截，误差再加一层。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>HNSW / IVF 用近似换延迟，必须报自己分布上的 Recall–延迟。</li><li>搜时预算与建时超参都要版本化。</li><li>权限过滤与遍历实现属于正确性，不只是性能。</li><li>出处：Malkov &amp; Yashunin HNSW；Jégou 等 IVF。</li></ul>',6))])}const A=o(c,[["render",m]]);export{E as __pageData,A as default};
